import 'package:appcraft_manifest_audit/appcraft_manifest_audit.dart';
import 'package:test/test.dart';

import 'fixtures.dart';

const String _recorded = r'''
# Generated by appcraft_manifest_audit.
# Update with: dart run appcraft_manifest_audit baseline
version: 1
variants:
  prod-release:
    application-id: com.demoshop
    permissions:
      ${applicationId}.DYNAMIC_RECEIVER_NOT_EXPORTED_PERMISSION:
        - androidx.core:core
      android.permission.INTERNET:
        - app/src/main
    components:
      activity#com.demoshop.MainActivity:
        - app/src/main
    suppressed:
      android.permission.READ_MEDIA_IMAGES:
        - app/src/main
''';

void main() {
  test('renders a file a reviewer can read, keys sorted', () {
    final rendered = Baseline.of(<Attribution>[prodRelease()]).render();

    expect(rendered, startsWith('# Generated by appcraft_manifest_audit.\n'));
    expect(rendered, contains('  prod-release:\n'));
    expect(rendered, contains('    application-id: com.demoshop\n'));
    expect(
      rendered,
      contains(
        '      android.permission.INTERNET:\n'
        '        - app/src/main\n',
      ),
    );
    expect(
      rendered,
      contains(
        r'      ${applicationId}.DYNAMIC_RECEIVER_NOT_EXPORTED_PERMISSION:'
        '\n'
        '        - androidx.core:core\n',
      ),
    );
  });

  test('reads back what it renders', () {
    final rendered = Baseline.of(<Attribution>[prodRelease()]).render();
    final parsed = Baseline.parse(rendered);

    expect(parsed.variants.keys, <String>['prod-release']);
    expect(parsed.variants['prod-release']!.applicationId, 'com.demoshop');
    expect(
      parsed.variants['prod-release']!.permissions.keys,
      containsAll(<String>[
        'android.permission.INTERNET',
        'com.google.android.gms.permission.AD_ID',
      ]),
    );
  });

  test('quotes a key YAML would read as something else', () {
    final rendered = Baseline.of(<Attribution>[
      attribute(
        variant: 'debug',
        report: parseMergerReport('''
uses-permission#android.permission.CAMERA
ADDED from [:shared_native] /build/shared_native/AndroidManifest.xml:4:5-67
'''),
        nodes: null,
      ),
    ]).render();

    expect(rendered, contains("        - ':shared_native'"));
    expect(
      Baseline.parse(rendered)
          .variants['debug']!
          .permissions['android.permission.CAMERA']!
          .single
          .key,
      ':shared_native',
    );
  });

  test('records an unattributed <uses-permission-sdk-23> as a permission', () {
    final section = BaselineVariant.of(attribute(
      variant: 'release',
      report: parseMergerReport('''
uses-permission#android.permission.INTERNET
ADDED from /app/src/main/AndroidManifest.xml:4:5-67
'''),
      nodes: const ManifestNodes(
        permissions: <String>{
          'android.permission.INTERNET',
          'uses-permission-sdk-23#android.permission.CAMERA',
        },
        components: <String>{},
      ),
    ));

    expect(
      section.permissions.keys,
      contains('uses-permission-sdk-23#android.permission.CAMERA'),
    );
    expect(section.components, isEmpty);
  });

  test('refuses a baseline of another format version', () {
    expect(
      () => Baseline.parse('version: 2\nvariants: {}\n'),
      throwsA(isA<BaselineException>()),
    );
  });

  test('refuses a file that is not YAML, or carries the wrong type', () {
    expect(
      () => Baseline.parse('version: 1\nvariants: [\n'),
      throwsA(isA<BaselineException>()),
    );
    expect(
      () => Baseline.parse(
        'version: 1\nvariants:\n  release:\n    application-id: 42\n',
      ),
      throwsA(isA<BaselineException>()),
    );
  });

  group('the diff', () {
    test('calls a new entry added, and fails the check by default', () {
      final diff = Baseline.parse(_recorded).diff(prodRelease());

      expect(
        diff.of(DiffKind.added).map((entry) => entry.key),
        containsAll(<String>[
          'com.google.android.gms.permission.AD_ID',
          'receiver#com.appsflyer.SingleInstallBroadcastReceiver',
        ]),
      );
      expect(diff.fails(strict: false), isTrue);
    });

    test('calls a lost suppression a failure', () {
      final diff = Baseline.parse(r'''
version: 1
variants:
  release:
    suppressed:
      android.permission.READ_MEDIA_IMAGES:
        - app/src/main
''').diff(attribute(
        variant: 'release',
        report: parseMergerReport('''
uses-permission#android.permission.READ_MEDIA_IMAGES
ADDED from [:open_filex] /build/open_filex/AndroidManifest.xml:7:5-79
'''),
        nodes: const ManifestNodes(
          permissions: <String>{'android.permission.READ_MEDIA_IMAGES'},
          components: <String>{},
        ),
      ));

      expect(diff.of(DiffKind.suppressionLost), hasLength(1));
      expect(diff.fails(strict: false), isTrue);
    });

    test('reports an owner change without failing by default', () {
      final diff = Baseline.parse('''
version: 1
variants:
  release:
    permissions:
      android.permission.CAMERA:
        - app/src/main
''').diff(attribute(
        variant: 'release',
        report: parseMergerReport('''
uses-permission#android.permission.CAMERA
ADDED from /app/src/main/AndroidManifest.xml:4:5-67
MERGED from [:camera_x] /build/camera_x/AndroidManifest.xml:7:5-79
'''),
        nodes: const ManifestNodes(
          permissions: <String>{'android.permission.CAMERA'},
          components: <String>{},
        ),
      ));

      expect(diff.of(DiffKind.ownerAdded).single.owners, <String>[':camera_x']);
      expect(diff.fails(strict: false), isFalse);
      expect(diff.fails(strict: true), isTrue);
    });

    test('reports a permission that disappeared, failing only under strict',
        () {
      final diff = Baseline.parse('''
version: 1
variants:
  release:
    permissions:
      android.permission.CAMERA:
        - app/src/main
      android.permission.INTERNET:
        - app/src/main
''').diff(attribute(
        variant: 'release',
        report: parseMergerReport('''
uses-permission#android.permission.INTERNET
ADDED from /app/src/main/AndroidManifest.xml:4:5-67
'''),
        nodes: const ManifestNodes(
          permissions: <String>{'android.permission.INTERNET'},
          components: <String>{},
        ),
      ));

      expect(
        diff.of(DiffKind.removed).single.key,
        'android.permission.CAMERA',
      );
      expect(diff.fails(strict: false), isFalse);
      expect(diff.fails(strict: true), isTrue);
    });

    test('reports a suppressed entry nothing asks for any more', () {
      final diff = Baseline.parse(r'''
version: 1
variants:
  release:
    permissions:
      android.permission.INTERNET:
        - app/src/main
    suppressed:
      android.permission.READ_MEDIA_IMAGES:
        - app/src/main
        - open_filex
''').diff(attribute(
        variant: 'release',
        report: parseMergerReport('''
uses-permission#android.permission.INTERNET
ADDED from /app/src/main/AndroidManifest.xml:4:5-67
'''),
        nodes: const ManifestNodes(
          permissions: <String>{'android.permission.INTERNET'},
          components: <String>{},
        ),
      ));

      expect(
        diff.of(DiffKind.removed).single.key,
        'android.permission.READ_MEDIA_IMAGES',
      );
      expect(diff.fails(strict: false), isFalse);
      expect(diff.fails(strict: true), isTrue);
    });

    test('reports a suppressed entry that changed owners', () {
      final diff = Baseline.parse(r'''
version: 1
variants:
  release:
    suppressed:
      android.permission.READ_MEDIA_IMAGES:
        - app/src/main
''').diff(attribute(
        variant: 'release',
        report: parseMergerReport('''
uses-permission#android.permission.READ_MEDIA_IMAGES
ADDED from /app/src/main/AndroidManifest.xml:4:5-67
MERGED from [:open_filex] /build/open_filex/AndroidManifest.xml:7:5-79
'''),
        nodes: const ManifestNodes(
          permissions: <String>{},
          components: <String>{},
        ),
      ));

      expect(
          diff.of(DiffKind.ownerAdded).single.owners, <String>[':open_filex']);
      expect(diff.fails(strict: false), isFalse);
    });

    test('reports a changed application id, failing only under strict', () {
      final diff = Baseline.parse('''
version: 1
variants:
  release:
    application-id: com.demoshop
    permissions:
      android.permission.INTERNET:
        - app/src/main
''').diff(attribute(
        variant: 'release',
        report: parseMergerReport('''
uses-permission#android.permission.INTERNET
ADDED from /app/src/main/AndroidManifest.xml:4:5-67
'''),
        nodes: const ManifestNodes(
          permissions: <String>{'android.permission.INTERNET'},
          components: <String>{},
          applicationId: 'com.demoshop.beta',
        ),
      ));

      expect(
        diff.of(DiffKind.applicationIdChanged).single.owners,
        <String>['com.demoshop', 'com.demoshop.beta'],
      );
      expect(diff.fails(strict: false), isFalse);
      expect(diff.fails(strict: true), isTrue);
    });

    test('is silent when nothing changed', () {
      final baseline = Baseline.of(<Attribution>[prodRelease()]);

      expect(baseline.diff(prodRelease()).isEmpty, isTrue);
    });

    test('is silent when nothing changed, suppressed entries included', () {
      final release =
          recordedAttribution('removed', 'release', 'AndroidManifest.xml');

      expect(Baseline.of(<Attribution>[release]).diff(release).isEmpty, isTrue);
    });

    test('treats a variant the baseline never saw as all new', () {
      final diff = Baseline.parse(_recorded).diff(recordedAttribution(
          'release', 'beta-release', 'AndroidManifest-beta.xml'));

      expect(diff.of(DiffKind.added), hasLength(4));
      expect(diff.of(DiffKind.removed), isEmpty);
      expect(diff.of(DiffKind.applicationIdChanged), isEmpty);
    });
  });
}
